-- ICT371 Question 8: Transport Fleet Maintenance (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q08_fleet; USE ict371_q08_fleet;
CREATE TABLE vehicles(vehicle_id INT AUTO_INCREMENT PRIMARY KEY,registration VARCHAR(30) NOT NULL UNIQUE,current_odometer INT NOT NULL,last_service_odometer INT NOT NULL,CHECK(current_odometer>=0 AND last_service_odometer>=0 AND last_service_odometer<=current_odometer));
CREATE TABLE trips(trip_id BIGINT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,trip_on DATETIME NOT NULL,start_odometer INT NOT NULL,end_odometer INT NOT NULL,FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id),CHECK(start_odometer>=0 AND end_odometer>start_odometer));
CREATE TABLE service_alerts(vehicle_id INT PRIMARY KEY,km_since_service INT NOT NULL,flagged_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id));
INSERT INTO vehicles(registration,current_odometer,last_service_odometer) VALUES('ABC-101',12000,8000),('ABC-202',22000,17000),('ABC-303',5000,2000);
DELIMITER $$
CREATE FUNCTION fn_service_due(p_vehicle_id INT) RETURNS BOOLEAN DETERMINISTIC READS SQL DATA BEGIN DECLARE v_due BOOLEAN; SELECT current_odometer-last_service_odometer>=5000 INTO v_due FROM vehicles WHERE vehicle_id=p_vehicle_id; IF v_due IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown vehicle'; END IF; RETURN v_due; END$$
CREATE TRIGGER trg_trip_odometer BEFORE INSERT ON trips FOR EACH ROW BEGIN DECLARE v_current INT; SELECT current_odometer INTO v_current FROM vehicles WHERE vehicle_id=NEW.vehicle_id FOR UPDATE; IF v_current IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown vehicle'; END IF; IF NEW.end_odometer<=NEW.start_odometer OR NEW.start_odometer<>v_current THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid mileage or start must match current odometer'; END IF; UPDATE vehicles SET current_odometer=NEW.end_odometer WHERE vehicle_id=NEW.vehicle_id; END$$
CREATE PROCEDURE pr_record_trip(IN p_vehicle_id INT,IN p_trip_on DATETIME,IN p_start INT,IN p_end INT) BEGIN IF NOT EXISTS(SELECT 1 FROM vehicles WHERE vehicle_id=p_vehicle_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown vehicle'; END IF; IF p_trip_on IS NULL OR p_start<0 OR p_end<=p_start THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid trip'; END IF; INSERT INTO trips(vehicle_id,trip_on,start_odometer,end_odometer) VALUES(p_vehicle_id,p_trip_on,p_start,p_end); END$$
CREATE PROCEDURE pr_refresh_service_alerts() BEGIN INSERT INTO service_alerts(vehicle_id,km_since_service,flagged_on) SELECT vehicle_id,current_odometer-last_service_odometer,CURRENT_TIMESTAMP FROM vehicles WHERE current_odometer-last_service_odometer>=5000 ON DUPLICATE KEY UPDATE km_since_service=VALUES(km_since_service),flagged_on=VALUES(flagged_on); DELETE FROM service_alerts WHERE vehicle_id NOT IN (SELECT vehicle_id FROM vehicles WHERE current_odometer-last_service_odometer>=5000); END$$
DELIMITER ;
-- Seed six trip rows by calling the procedure after its trigger has been installed.
CALL pr_record_trip(1,NOW(),12000,12500); CALL pr_record_trip(1,NOW(),12500,13000); CALL pr_record_trip(2,NOW(),22000,22500); CALL pr_record_trip(2,NOW(),22500,23000); CALL pr_record_trip(3,NOW(),5000,5200); CALL pr_record_trip(3,NOW(),5200,5500);
CREATE VIEW v_service_due AS SELECT registration,current_odometer-last_service_odometer km_since_service FROM vehicles WHERE current_odometer-last_service_odometer>=5000;
CREATE INDEX ix_trips_vehicle_date ON trips(vehicle_id,trip_on);
EXPLAIN SELECT trip_id,trip_on,start_odometer,end_odometer FROM trips WHERE vehicle_id=1 AND trip_on BETWEEN '2026-01-01' AND '2026-12-31';
SET GLOBAL event_scheduler=ON; CREATE EVENT IF NOT EXISTS ev_refresh_service_alerts ON SCHEDULE EVERY 1 WEEK STARTS (TIMESTAMP(CURRENT_DATE+INTERVAL (7-DAYOFWEEK(CURRENT_DATE)+2) DAY,'06:00:00')) DO CALL pr_refresh_service_alerts();
